import{_ as n,o as i,c as o,a5 as t}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"G7 — Subscription & Billing (mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g7-subscription-billing/spec.md","filePath":"mobile/features/g7-subscription-billing/spec.md"}'),c={name:"mobile/features/g7-subscription-billing/spec.md"};function a(d,e,l,r,h,s){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="g7-—-subscription-billing-mobile" tabindex="-1">G7 — Subscription &amp; Billing (mobile) <a class="header-anchor" href="#g7-—-subscription-billing-mobile" aria-label="Permalink to &quot;G7 — Subscription &amp; Billing (mobile)&quot;">​</a></h1><p>&gt; Trạng thái: DRAFT — tài liệu đặc tả, KHÔNG code. Tham chiếu <code>docs/mobile/mobile-app-plan.md</code> (bảng mục 3, dòng G7) và <code>docs/ba/08-subscription-billing.md</code>.</p><h2 id="_1-muc-tieu-pham-vi" tabindex="-1">1. Mục tiêu &amp; phạm vi <a class="header-anchor" href="#_1-muc-tieu-pham-vi" aria-label="Permalink to &quot;1. Mục tiêu &amp; phạm vi&quot;">​</a></h2><p>Mobile G7 cho phép user:</p><ul><li>Xem plan hiện tại (Basic/Pro/Enterprise), ngày hết hạn/renewal, trạng thái subscription.</li><li>Xem danh sách plan khả dụng để so sánh (đọc, không nhất thiết mua ngay trong app — xem mục 7).</li><li>Xem lịch sử invoice/giao dịch của Agency, xem chi tiết 1 invoice, xem trạng thái thanh toán SePay.</li><li>Xem AI credit allowance gắn với plan: hạn mức tháng, đã dùng, còn lại (cả cấp Agency và cấp cá nhân nếu Owner có set limit).</li></ul><p><strong>Lưu ý quan trọng:</strong> hành động &quot;mua/upgrade/downgrade plan&quot; có rủi ro chính sách App Store khi làm trong app trên iOS (xem mục 7) — khuyến nghị của tài liệu này là KHÔNG thực hiện thanh toán thật trong app ở G7, chỉ đọc + điều hướng ra ngoài. Đây là đề xuất của người viết tài liệu, <strong>chưa được user xác nhận</strong>, cần chốt trước khi lên implementation plan.</p><h2 id="_2-fr-tham-chieu" tabindex="-1">2. FR tham chiếu <a class="header-anchor" href="#_2-fr-tham-chieu" aria-label="Permalink to &quot;2. FR tham chiếu&quot;">​</a></h2><p>Từ <code>docs/ba/08-subscription-billing.md</code> (FR 3.9.1–3.9.7):</p><table tabindex="0"><thead><tr><th>FR</th><th>Tên</th><th>Role</th><th>Mobile G7 làm gì</th></tr></thead><tbody><tr><td>3.9.1</td><td>Upgrade Plan</td><td>USER</td><td>Đọc danh sách plan, xem so sánh. Hành động &quot;upgrade&quot; thật → điều hướng ra web (mục 7), không build checkout trong app.</td></tr><tr><td>3.9.2</td><td>Downgrade Plan</td><td>OWNER</td><td>Tương tự — xem, không thao tác cancel/downgrade thật trong G7 (có thể xét lại ở giai đoạn sau nếu không đụng thanh toán).</td></tr><tr><td>3.9.3</td><td>Make Payment (PayOS theo doc BA, thực tế code dùng SePay)</td><td>USER</td><td>KHÔNG làm ở mobile G7 — xem mục 7 và mục 8 (có sai khác BA doc vs code, cần hỏi lại).</td></tr><tr><td>3.9.4</td><td>View Invoice History</td><td>OWNER</td><td>Làm đầy đủ: list + detail + trạng thái thanh toán.</td></tr><tr><td>3.9.5</td><td>View AI Credit Tracking</td><td>CREATOR, OWNER</td><td>Làm đầy đủ: allowance/used/remaining theo Agency và theo Creator.</td></tr><tr><td>3.9.6</td><td>Buy Credit</td><td>OWNER</td><td>KHÔNG làm ở G7 (đụng thanh toán thật) — chỉ xem, điều hướng ra web nếu cần mua.</td></tr><tr><td>3.9.7</td><td>Set Credit</td><td>OWNER</td><td>Không trong phạm vi đọc liệu có cần — đánh giá sau; nếu làm thì là ghi dữ liệu không phải tiền, rủi ro thấp, có thể đưa vào G7 nếu còn thời gian (xem mục 7).</td></tr></tbody></table><h2 id="_3-api-can-dung-đa-đoc-code-khong-đoan" tabindex="-1">3. API cần dùng (đã đọc code, không đoán) <a class="header-anchor" href="#_3-api-can-dung-đa-đoc-code-khong-đoan" aria-label="Permalink to &quot;3. API cần dùng (đã đọc code, không đoán)&quot;">​</a></h2><p>Business-service có <strong>2 hệ thống plan/billing song song</strong> đang hoạt động — cần lưu ý khi tích hợp mobile:</p><h3 id="_3a-he-cu-—-subscriptioncontroller-api-v1-subscription" tabindex="-1">3a. Hệ cũ — <code>SubscriptionController</code> (<code>/api/v1/subscription</code>) <a class="header-anchor" href="#_3a-he-cu-—-subscriptioncontroller-api-v1-subscription" aria-label="Permalink to &quot;3a. Hệ cũ — `SubscriptionController` (`/api/v1/subscription`)&quot;">​</a></h3><p>Model: <code>SubscriptionPlan</code> (<code>model/SubscriptionPlan.java</code>), <code>UserSubscription</code> (<code>model/UserSubscription.java</code>). Plan gắn theo <strong>User</strong> (không theo Agency).</p><ul><li><code>GET /api/v1/subscription/plans</code> → <code>List&lt;SubscriptionPlanResponse&gt;</code> — field: <code>id, name (BASIC/PRO/ENTERPRISE), displayName, priceMonthly, maxWorkspaces, aiCreditsMonth, features (JSON string), isActive, createdAt</code>.</li><li><code>GET /api/v1/subscription/me</code> → <code>UserSubscriptionResponse</code> — field: <code>id, userId, planId, status (enum SubscriptionStatus, default TRIALING), currentPeriodStart, currentPeriodEnd, cancelledAt, createdAt</code>.</li><li><code>POST /api/v1/subscription</code> (body <code>SubscribeRequest</code>) → subscribe/upgrade.</li><li><code>POST /api/v1/subscription/cancel</code> → downgrade/hủy.</li></ul><h3 id="_3b-he-moi-—-billing-plan-catalog-agency-billing-api-v1-billing" tabindex="-1">3b. Hệ mới — Billing Plan Catalog + Agency Billing (<code>/api/v1/billing/...</code>) <a class="header-anchor" href="#_3b-he-moi-—-billing-plan-catalog-agency-billing-api-v1-billing" aria-label="Permalink to &quot;3b. Hệ mới — Billing Plan Catalog + Agency Billing (`/api/v1/billing/...`)&quot;">​</a></h3><p>Model: <code>BillingPlanResponse</code> — plan versioned, có <code>checkoutEnabled</code>, <code>isSellable</code>, gắn theo <strong>billingScope</strong> (có vẻ theo Agency, field <code>monthlyAiCredits</code> thay vì <code>aiCreditsMonth</code>).</p><ul><li><code>GET /api/v1/billing/plans</code> (<code>BillingPlanController</code>) → <code>List&lt;BillingPlanResponse&gt;</code> — field: <code>id, code, version, displayName, billingScope, priceMonthly, currency, maxActiveWorkspaces, maxInternalMembers, maxClients, storageLimitBytes, monthlyAiCredits, maxConcurrentAiJobs, versionRetentionDays, trashRetentionDays, activityRetentionDays, maxPersonalSpaces, isSellable, checkoutEnabled</code>.</li><li><code>GET /api/v1/billing/agencies/{agencyId}/subscription</code> (<code>BillingController</code>) → <code>AgencySubscriptionResponse</code> — subscription hiện tại của Agency.</li><li><code>POST /api/v1/billing/agencies/{agencyId}/orders</code> (header <code>Idempotency-Key</code> bắt buộc, body <code>action=UPGRADE</code> mặc định) → tạo order SePay, trả <code>AgencyBillingOrderResponse</code> (có <code>qrUrl</code>, <code>status PENDING_PAYMENT</code>, xem mục 6).</li><li><code>GET /api/v1/billing/agencies/{agencyId}/orders/{orderId}</code> → trạng thái 1 order.</li><li><code>POST /api/v1/billing/webhooks/sepay</code> — webhook SePay xác nhận thanh toán, KHÔNG liên quan mobile client trực tiếp.</li></ul><h3 id="_3c-invoice-history-invoicehistorycontroller-api-v1-billing-agencies-agencyid-invoices" tabindex="-1">3c. Invoice history (<code>InvoiceHistoryController</code>, <code>/api/v1/billing/agencies/{agencyId}/invoices</code>) <a class="header-anchor" href="#_3c-invoice-history-invoicehistorycontroller-api-v1-billing-agencies-agencyid-invoices" aria-label="Permalink to &quot;3c. Invoice history (`InvoiceHistoryController`, `/api/v1/billing/agencies/{agencyId}/invoices`)&quot;">​</a></h3><ul><li><code>GET /invoices?cursor&amp;limit&amp;status&amp;kind&amp;from&amp;to</code> → <code>InvoiceHistoryResponse { items: List&lt;Item&gt;, nextCursor }</code>. <code>Item</code> field: <code>id, agencyId, agencyName, payerUserId, kind, status, planCode, amount, currency, createdAt, paidAt, fulfilledAt, expiresAt, periodStart, periodEnd, transferContent, receiptAvailable</code>.</li><li><code>GET /invoices/{orderId}</code> → <code>Detail { order: Item, productSnapshot, payments: List&lt;Payment&gt;, reviewReasons }</code>. <code>Payment</code> field: <code>id, amount, currency, providerReference, verificationState, paidAt</code>.</li><li><code>GET /invoices/{orderId}/sepay-transactions?page</code> → <code>SePayHistoryResponse</code> — tra soát transaction SePay thủ công (admin-ish; mobile có thể không cần).</li><li><code>GET /invoices/{orderId}/receipt</code> → file <code>.txt</code> receipt (response <code>ResponseEntity&lt;byte[]&gt;</code>, content-type <code>text/plain</code>, header <code>Content-Disposition attachment</code>) — mobile cần xử lý tải file, không phải JSON.</li></ul><h3 id="_3d-legacy-billing-transactions-ai-credit-billingcontroller-api-v1-billing" tabindex="-1">3d. Legacy billing/transactions + AI credit (<code>BillingController</code>, <code>/api/v1/billing</code>) <a class="header-anchor" href="#_3d-legacy-billing-transactions-ai-credit-billingcontroller-api-v1-billing" aria-label="Permalink to &quot;3d. Legacy billing/transactions + AI credit (`BillingController`, `/api/v1/billing`)&quot;">​</a></h3><ul><li><code>GET /api/v1/billing/transactions</code> → <code>List&lt;TransactionResponse&gt;</code> (model <code>Transaction.java</code>) — route cũ cho FR 3.9.4, có thể trùng lặp với 3c; cần hỏi BE đang dùng route nào là chính thức.</li><li><code>GET /api/v1/billing/transactions/{transactionId}</code> → chi tiết 1 transaction.</li><li><code>POST /api/v1/billing/credits/buy</code> (body <code>BuyCreditRequest</code>) → FR 3.9.6, KHÔNG dùng ở mobile G7.</li><li><code>GET /api/v1/billing/credits/{agencyId}/usage?month=YYYY-MM</code> → <code>CreditUsageResponse</code> — FR 3.9.5, dùng được ở G7 (đọc only).</li><li><code>PUT /api/v1/billing/credits/{agencyId}/limits</code> (body <code>SetCreditLimitRequest</code>) → FR 3.9.7, Owner-only, cân nhắc đưa vào G7 nếu còn thời gian (không phải thanh toán thật, chỉ set số nguyên).</li><li><code>POST /api/v1/billing/payments</code> — &quot;Legacy user-scoped payment stub&quot; theo comment trong code, KHÔNG dùng.</li></ul><p><strong>Khuyến nghị cho mobile:</strong> ưu tiên hệ 3b (<code>/api/v1/billing/...</code> Agency-scoped) vì có <code>checkoutEnabled</code>/<code>isSellable</code> rõ ràng và khớp model 3 tầng Agency trong BA doc; hệ 3a (<code>/api/v1/subscription</code>) là User-scoped, có thể là code cũ hơn chưa dọn — <strong>cần hỏi BE team xác nhận route nào là nguồn sự thật hiện tại</strong> trước khi code thật (câu hỏi mở, mục 8).</p><h2 id="_4-luong-man-hinh" tabindex="-1">4. Luồng màn hình <a class="header-anchor" href="#_4-luong-man-hinh" aria-label="Permalink to &quot;4. Luồng màn hình&quot;">​</a></h2><ol><li><strong>Current Plan screen</strong> — gọi <code>GET /billing/agencies/{agencyId}/subscription</code> (hoặc <code>/subscription/me</code> nếu BE xác nhận dùng hệ cũ): hiển thị plan name, trạng thái, <code>currentPeriodEnd</code> (ngày renew), và block AI credit allowance (gọi thêm <code>GET /billing/credits/{agencyId}/usage?month=&lt;tháng hiện tại&gt;</code> — hiển thị used/remaining theo <code>AiCreditService.Balance</code>: <code>allowance, used, remaining, creatorLimit, creatorUsed</code>).</li><li><strong>Plan comparison list</strong> — gọi <code>GET /billing/plans</code>, hiển thị card mỗi plan (<code>displayName, priceMonthly, monthlyAiCredits, maxActiveWorkspaces, maxInternalMembers, isSellable, checkoutEnabled</code>). Nút hành động &quot;Nâng cấp&quot; trên mỗi card <strong>không mở checkout trong app</strong> — mở deep link ra trình duyệt ngoài tới trang <code>/subscription/checkout?tier=...</code> của web (xem mục 7).</li><li><strong>Upgrade confirmation</strong> — KHÔNG có trong G7 mobile (xảy ra trên web sau khi mở deep link).</li><li><strong>Invoice history list</strong> — gọi <code>GET /invoices</code> (paginate bằng <code>cursor</code>/<code>nextCursor</code>), hiển thị <code>planCode, amount, currency, status, createdAt, paidAt</code>. Có filter <code>status</code>/<code>kind</code>/khoảng ngày nếu UI cho phép.</li><li><strong>Invoice detail</strong> — gọi <code>GET /invoices/{orderId}</code>, hiển thị <code>productSnapshot</code>, danh sách <code>payments</code> (verificationState từng payment), <code>reviewReasons</code> nếu có. Nút &quot;Tải receipt&quot; gọi <code>GET /invoices/{orderId}/receipt</code> — xử lý file <code>.txt</code> tải xuống (dùng file system API của Expo, không parse JSON).</li></ol><h2 id="_5-state-cache-—-tanstack-query-keys" tabindex="-1">5. State &amp; cache — TanStack Query keys <a class="header-anchor" href="#_5-state-cache-—-tanstack-query-keys" aria-label="Permalink to &quot;5. State &amp; cache — TanStack Query keys&quot;">​</a></h2><ul><li><code>[&#39;billing&#39;, &#39;agency&#39;, agencyId, &#39;subscription&#39;]</code> — current plan, staleTime ngắn (vài phút) vì có thể đổi qua webhook SePay.</li><li><code>[&#39;billing&#39;, &#39;plans&#39;]</code> — catalog plan, cache lâu hơn (ít đổi), có thể để <code>staleTime: 1 hour</code>.</li><li><code>[&#39;billing&#39;, &#39;agency&#39;, agencyId, &#39;credits&#39;, month]</code> — AI credit usage theo tháng, key theo <code>month</code> để tránh lẫn dữ liệu tháng cũ.</li><li><code>[&#39;billing&#39;, &#39;agency&#39;, agencyId, &#39;invoices&#39;, filters]</code> — invoice list, dùng <code>useInfiniteQuery</code> với <code>cursor</code>/<code>nextCursor</code> (không dùng offset).</li><li><code>[&#39;billing&#39;, &#39;agency&#39;, agencyId, &#39;invoices&#39;, orderId]</code> — invoice detail, invalidate khi list refetch nếu cùng <code>orderId</code>.</li><li>Không cache receipt file (luôn fetch mới khi user bấm tải, vì nội dung có thể đổi nếu trạng thái order thay đổi).</li></ul><h2 id="_6-business-rules-đac-biet-tu-docs-ba-08-subscription-billing-md" tabindex="-1">6. Business rules đặc biệt (từ <code>docs/ba/08-subscription-billing.md</code>) <a class="header-anchor" href="#_6-business-rules-đac-biet-tu-docs-ba-08-subscription-billing-md" aria-label="Permalink to &quot;6. Business rules đặc biệt (từ `docs/ba/08-subscription-billing.md`)&quot;">​</a></h2><ul><li>Plan (Basic/Pro/Enterprise) gắn với <strong>User/Owner</strong>, ảnh hưởng toàn bộ Agency của Owner đó — không mua riêng theo Workspace (mô hình 3 tầng: User → Agency → Workspace).</li><li>AI credit có <strong>2 lớp</strong>: hạn mức Agency (từ plan) và hạn mức Creator (do Owner set qua <code>Set Credit</code>, FR 3.9.7) — <code>AiCreditService.Balance.remaining()</code> = <code>min(agency_remaining, creator_limit - creator_used)</code> nếu Owner có set limit cho Creator đó, ngược lại chỉ bị chặn bởi agency remainder.</li><li>Hạn mức Creator là <strong>hard limit</strong> (CONFIRMED 2026-09-17): hết credit → chặn hẳn thao tác AI tiếp theo, không phải soft warning, tới khi Owner cấp thêm hoặc sang kỳ mới.</li><li>Mặc định hệ thống fallback: 10 credit/thành viên/kỳ nếu Owner chưa set riêng.</li><li>Credit Plan (theo allowance tháng) không rollover sang kỳ sau; dùng credit Plan trước, credit mua thêm (Buy Credit) sau. Credit mua thêm KHÔNG hết hạn, vẫn dùng được khi subscription hết hạn/hủy.</li><li>Subscription hết hạn vẫn reset hạn mức hàng tháng theo anchor chu kỳ cũ (không dừng reset khi hủy).</li><li>Thanh toán qua <strong>SePay</strong> (không phải PayOS như <code>08-subscription-billing.md</code> mô tả ở FR 3.9.3 — đây là điểm sai khác giữa BA doc và code thực tế, xem mục 8): flow là tạo order → BE trả <code>qrUrl</code> (ảnh QR chuyển khoản ngân hàng) → hiển thị QR trong <code>AgencyPaymentPanel.tsx</code> (web) → user chuyển khoản thật qua app ngân hàng của họ → SePay gọi webhook <code>POST /billing/webhooks/sepay</code> xác nhận → order chuyển trạng thái <code>PAID</code>/fulfilled. Đây không phải redirect sang trang thanh toán của provider, mà là hiển thị ảnh QR tĩnh ngay trong UI, chờ webhook.</li><li><code>BillingController.createPayment</code> (<code>/billing/payments</code>) được chú thích trong code là <strong>&quot;Legacy user-scoped payment stub&quot;</strong> — không phải luồng chính thức hiện tại.</li></ul><h2 id="_7-viec-khong-lam-o-g7-va-khuyen-nghi-—-đay-la-đe-xuat-chua-đuoc-user-xac-nhan" tabindex="-1">7. Việc KHÔNG làm ở G7 (và khuyến nghị — đây là đề xuất, CHƯA được user xác nhận) <a class="header-anchor" href="#_7-viec-khong-lam-o-g7-va-khuyen-nghi-—-đay-la-đe-xuat-chua-đuoc-user-xac-nhan" aria-label="Permalink to &quot;7. Việc KHÔNG làm ở G7 (và khuyến nghị — đây là đề xuất, CHƯA được user xác nhận)&quot;">​</a></h2><p><strong>Không build luồng mua/upgrade/thanh toán thật trong app mobile ở giai đoạn này.</strong> Lý do:</p><ul><li>Flow thanh toán thật hiện tại (SePay QR + chuyển khoản ngân hàng thật, xem mục 6) là thanh toán tiền thật ngoài hệ sinh thái Apple/Google. Apple App Store Review Guidelines (mục 3.1.1) yêu cầu nội dung số bán trong app (gồm subscription) phải dùng In-App Purchase (IAP) của Apple nếu app được publish công khai trên App Store — route thanh toán ngân hàng/QR riêng hiển thị trong app (dù là ảnh tĩnh, không phải WebView) vẫn được xem là &quot;thanh toán ngoài IAP cho nội dung số&quot;, vi phạm chính sách nếu app public.</li><li><strong>Vì mobile-app-plan.md đã chốt: đây là bản demo nội bộ qua Expo Go / TestFlight / ad-hoc, KHÔNG public release App Store</strong> — rủi ro chính sách này KHÔNG chặn demo capstone. Nó chỉ trở thành vấn đề thật nếu dự án sau này publish công khai lên App Store.</li><li>Dù vậy, để tránh phải viết lại toàn bộ UI khi/nếu app public hoá sau capstone, khuyến nghị (đề xuất riêng, cần confirm): mobile G7 chỉ làm <strong>READ-ONLY</strong> — xem plan, xem invoice, xem credit. Hành động &quot;Nâng cấp/Mua thêm credit&quot; chỉ có nút <strong>&quot;Mở trên web&quot;</strong> dùng <code>Linking.openURL()</code> của Expo để mở trình duyệt ngoài (Safari/Chrome) tới trang checkout web (<code>/subscription/checkout?tier=...</code>), KHÔNG mở trong WebView nhúng trong app. Browser ngoài hệ app → không tính là &quot;mua trong app&quot; theo cách hiểu phổ biến của Apple review, giữ app sẵn sàng public hoá sau này mà không phải sửa lại kiến trúc thanh toán.</li><li>Không làm: <code>POST /subscription</code>, <code>POST /billing/agencies/{agencyId}/orders</code>, <code>POST /billing/credits/buy</code>, <code>POST /subscription/cancel</code>, hiển thị QR SePay trong app.</li><li>Có thể xét làm nếu còn thời gian (rủi ro thấp, không phải tiền): <code>PUT /billing/credits/{agencyId}/limits</code> (Set Credit, FR 3.9.7) — chỉ ghi số nguyên hạn mức, không chạm luồng thanh toán.</li></ul><h2 id="_8-rui-ro-cau-hoi-mo" tabindex="-1">8. Rủi ro / câu hỏi mở <a class="header-anchor" href="#_8-rui-ro-cau-hoi-mo" aria-label="Permalink to &quot;8. Rủi ro / câu hỏi mở&quot;">​</a></h2><ol><li><strong>BA doc vs code sai khác về payment gateway:</strong> <code>docs/ba/08-subscription-billing.md</code> FR 3.9.3 ghi &quot;Make Payment (PayOS)&quot; nhưng code thực tế (<code>SePayProperties</code>, <code>SePayTransactionClient</code>, <code>BillingController.sepayWebhook</code>, <code>AgencyPaymentPanel.tsx</code> dùng <code>qrUrl</code>) dùng <strong>SePay</strong> (QR chuyển khoản ngân hàng), không thấy PayOS/VNPay/Momo/Stripe trong codebase. Cần hỏi BA/PM xác nhận đây là update chưa đồng bộ vào doc, hoặc PayOS từng được dự tính nhưng đã đổi sang SePay.</li><li><strong>Hai hệ plan song song:</strong> <code>SubscriptionController</code>/<code>SubscriptionPlan</code> (User-scoped, enum BASIC/PRO/ENTERPRISE, field <code>aiCreditsMonth</code>) vs <code>BillingPlanController</code>/<code>BillingPlanResponse</code> (Agency-scoped, versioned, field <code>monthlyAiCredits</code>, có <code>checkoutEnabled</code>/<code>isSellable</code>). Web frontend (<code>brandhub-web/src/pages/subscription/</code>) dùng hệ nào là chính? Cần xác nhận route nào mobile nên gọi — tài liệu này tạm ưu tiên hệ 3b vì khớp BA doc hơn, nhưng cần BE xác nhận trước khi code.</li><li><strong><code>/billing/transactions</code> vs <code>/billing/agencies/{agencyId}/invoices</code>:</strong> có vẻ trùng chức năng View Invoice History (FR 3.9.4) — cần hỏi route nào đang active/được web dùng thật (ground truth) trước khi mobile tích hợp, tránh build trên route đã deprecated.</li><li><strong>Khuyến nghị &quot;mở web ngoài thay vì mua trong app&quot; ở mục 7 là đề xuất của tài liệu này, chưa phải quyết định đã chốt</strong> — cần user/PM xác nhận trước khi đưa vào implementation plan thật.</li><li><strong>Độ chính xác mapping plan → AI credit:</strong> số liệu cụ thể (giá, số credit mỗi plan) nằm trong DB seed/migration, không nằm trong code Java đọc được trực tiếp ở các file đã xem — nếu cần số thật để demo UI, phải tra thêm seed data (<code>AdminDemoSeeder.java</code>) hoặc DB, chưa làm ở phạm vi tài liệu này.</li></ol>',33)])])}const p=n(c,[["render",a]]);export{u as __pageData,p as default};
